import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            M = int(next(iterator))
            N = int(next(iterator))
            s = next(iterator)
        except StopIteration:
            break

        n = len(s)

        def count_exact(target_char, target_count):
            if target_count < 0:
                return 0

            positions = [-1]
            for i, char in enumerate(s):
                if char == target_char:
                    positions.append(i)
            positions.append(n)

            total_occurrences = len(positions) - 2

            if target_count == 0:
                count = 0
                for i in range(len(positions) - 1):
                    left = positions[i]
                    right = positions[i + 1]
                    segment_len = right - left - 1
                    if segment_len > 0:
                        count += segment_len * (segment_len + 1) // 2
                return count

            if target_count > total_occurrences:
                return 0

            count = 0
            for i in range(1, total_occurrences - target_count + 2):
                start_idx = positions[i]
                end_idx = positions[i + target_count]

                left_options = start_idx - positions[i - 1]
                right_options = positions[i + target_count + 1] - end_idx

                count += left_options * right_options

            return count

        count_r = count_exact('R', M)
        count_k = count_exact('K', N)

        results.append(f"{count_r} {count_k}")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
